// PROTOTYPE — wayfinder P5. Throwaway.
// A package that IS granted. Its job is to hand the denied package every
// context-carrying object it can, so the denied package can try to re-enter
// this package's async context and read authority from inside it.

import { AsyncResource, AsyncLocalStorage } from "node:async_hooks";

export const als = new AsyncLocalStorage();

// Constructed here, so #snapshot captures *this* package's async context.
export function makeResource() {
  return new AsyncResource("granted-resource");
}

// A resource constructed while this package is genuinely mid-callback.
export function makeResourceDeepInStack() {
  return als.run({ owner: "granted" }, () => new AsyncResource("granted-deep"));
}

// A bound function factory: whatever the denied package passes in gets bound to
// this package's context.
export function bindIntoOurContext(fn) {
  return als.run({ owner: "granted" }, () => AsyncLocalStorage.bind(fn));
}

export function snapshotOurContext() {
  return als.run({ owner: "granted" }, () => AsyncLocalStorage.snapshot());
}

// Invoke a callback the denied package gave us, from deep inside our own stack.
export function callFromOurStack(fn) {
  return als.run({ owner: "granted" }, () => fn());
}

// Proof this package really does hold authority.
export const grantedSees = () => typeof globalThis.fetch;
